"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1882],{67499:e=>{e.exports=JSON.parse('{"functions":[{"name":"getLanguageSubtag","desc":"Returns the lowercased primary language subtag, or nil when the input has no\\nlanguage subtag (nil, non-string, empty, or leading punctuation/digits).\\n\\n```lua\\nResolveLocaleUtils.getLanguageSubtag(\\"en-us\\") --\x3e \\"en\\"\\nResolveLocaleUtils.getLanguageSubtag(\\"zh_Hant_TW\\") --\x3e \\"zh\\"\\nResolveLocaleUtils.getLanguageSubtag(\\"PT-BR\\") --\x3e \\"pt\\"\\nResolveLocaleUtils.getLanguageSubtag(nil) --\x3e nil\\n```","params":[{"name":"locale","desc":"","lua_type":"string?"}],"returns":[{"desc":"","lua_type":"string?"}],"function_type":"static","source":{"line":40,"path":"src/clienttranslator/src/Shared/Utils/ResolveLocaleUtils.lua"}},{"name":"getScriptSubtag","desc":"Returns the script subtag, or nil when the locale does not carry one. A script subtag is\\nthe four-letter subtag directly after the language (`zh-Hant`, `zh-Hant-TW`, `sr-Latn`);\\na two-letter or three-digit subtag in that position is a region, not a script.\\n\\n```lua\\nResolveLocaleUtils.getScriptSubtag(\\"zh-Hant-TW\\") --\x3e \\"hant\\"\\nResolveLocaleUtils.getScriptSubtag(\\"zh-TW\\") --\x3e nil\\n```","params":[{"name":"locale","desc":"","lua_type":"string?"}],"returns":[{"desc":"","lua_type":"string?"}],"function_type":"static","source":{"line":95,"path":"src/clienttranslator/src/Shared/Utils/ResolveLocaleUtils.lua"}},{"name":"isTraditionalChinese","desc":"Whether a Chinese locale is Traditional. The `hant` script subtag, and the `tw` / `hk` /\\n`mo` regions, are Traditional; everything else (`hans`, `cn`, `sg`, bare `zh`) is\\nSimplified. Only meaningful for `zh` locales.","params":[{"name":"locale","desc":"","lua_type":"string?"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":118,"path":"src/clienttranslator/src/Shared/Utils/ResolveLocaleUtils.lua"}},{"name":"isCompatibleLocale","desc":"Whether two locales are close enough that one can be read in place of the other: the same\\nlanguage, written in the same script.\\n\\nRegional variants of a language substitute for one another, so `es-mx` reads `es-es` and\\n`en-gb` reads `en-us`. Scripts do not: Traditional and Simplified Chinese are not mutually\\nreadable, so `zh-tw` never reads `zh-cn`, whether the script is spelled out (`zh-Hant` vs\\n`zh-Hans`) or implied by region (`zh-tw` vs `zh-cn`). The same holds for any language\\nwhose locales carry differing script subtags, such as `sr-Latn` and `sr-Cyrl`.\\n\\n```lua\\nResolveLocaleUtils.isCompatibleLocale(\\"es-mx\\", \\"es-es\\") --\x3e true\\nResolveLocaleUtils.isCompatibleLocale(\\"zh-tw\\", \\"zh-cn\\") --\x3e false\\nResolveLocaleUtils.isCompatibleLocale(\\"pt-br\\", \\"en-us\\") --\x3e false\\n```","params":[{"name":"locale","desc":"","lua_type":"string?"},{"name":"otherLocale","desc":"","lua_type":"string?"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":161,"path":"src/clienttranslator/src/Shared/Utils/ResolveLocaleUtils.lua"}},{"name":"resolveClosestKey","desc":"Resolves a locale to the best-matching key present in `availableLocales`:\\n\\n1. Exact (case-insensitive) match.\\n2. Chinese Traditional/Simplified routing to whichever variant keys exist.\\n3. Closest key sharing the language subtag (smallest key, so the pick is\\n   deterministic), so e.g. `en-gb` falls back to `en-us` and `es-mx` to `es-es`\\n   rather than to an unrelated default.\\n\\nReturns nil when nothing shares the language subtag; callers apply their own\\ndefault in that case.","params":[{"name":"locale","desc":"","lua_type":"string?"},{"name":"availableLocales","desc":"","lua_type":"{ [string]: T }"}],"returns":[{"desc":"","lua_type":"string?"}],"function_type":"static","source":{"line":203,"path":"src/clienttranslator/src/Shared/Utils/ResolveLocaleUtils.lua"}}],"properties":[],"types":[],"name":"ResolveLocaleUtils","desc":"Shared locale-id parsing and resolution. Keeps the \\"given a locale like\\n`en-us`, what do we actually use?\\" logic in one place so number formatting,\\ndialog pacing, and any other locale-sensitive feature resolve identically.\\n\\nLocale ids follow BCP-47-ish shapes: a language subtag, then optional script\\nand/or region subtags separated by `-` (or sometimes `_`), e.g. `en`, `en-us`,\\n`pt-br`, `zh-Hant-TW`. Matching is case-insensitive.","source":{"line":13,"path":"src/clienttranslator/src/Shared/Utils/ResolveLocaleUtils.lua"}}')}}]);